#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin>>n;
    struct Piece{int k;vector<pair<int,int>>cells;};
    vector<Piece> pieces(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for(int j=0;j<pieces[i].k;j++) cin>>pieces[i].cells[j].first>>pieces[i].cells[j].second;
        totalCells+=pieces[i].k;
    }
    struct Ori{vector<pair<int,int>>cells;int w,h,r,f;};
    vector<vector<Ori>> allOris(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>>seen;
        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                vector<pair<int,int>>tc;
                for(auto[ox,oy]:pieces[i].cells){
                    int nx=ox,ny=oy;
                    if(f) nx=-nx;
                    for(int q=0;q<r;q++){int t=nx;nx=ny;ny=-t;}
                    tc.push_back({nx,ny});
                }
                int mnx=INT_MAX,mny=INT_MAX;
                for(auto[x,y]:tc){mnx=min(mnx,x);mny=min(mny,y);}
                for(auto&[x,y]:tc){x-=mnx;y-=mny;}
                sort(tc.begin(),tc.end());
                if(seen.insert(tc).second){
                    int w=0,h=0;
                    for(auto[x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                    allOris[i].push_back({tc,w,h,r,f});
                }
            }
        }
    }
    vector<int>order(n);iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return pieces[a].k>pieces[b].k;});
    auto st=chrono::steady_clock::now();
    auto el=[&]{return chrono::duration<double>(chrono::steady_clock::now()-st).count();};
    int minPW=0;
    for(int i=0;i<n;i++)for(auto&o:allOris[i])minPW=max(minPW,min(o.w,o.h));
    long long bestArea=4e18;int bestH=0,bestW=0;
    struct PR{int x,y,r,f;};
    vector<PR>bestPl(n);
    double sq=sqrt((double)totalCells);
    set<int>ws;
    for(int w=max(minPW,(int)(sq*0.3));w<=min(totalCells,(int)(sq*5)+2);w++)ws.insert(w);
    for(int W:ws){
        if(el()>8.0&&bestArea<4e18)break;
        int maxH=min(totalCells+1,max((totalCells+W-1)/W*4+50,200));
        vector<int>hmap(W,0);
        vector<vector<bool>>grid(W,vector<bool>(maxH,false));
        vector<PR>pl(n);int curMax=0;bool fail=false;
        for(int idx=0;idx<n&&!fail;idx++){
            int pi=order[idx];int bs=INT_MAX,bx=-1,by=-1,bo=-1;
            for(int oi=0;oi<(int)allOris[pi].size();oi++){
                auto&ori=allOris[pi][oi];
                if(ori.w>W)continue;
                for(int x=0;x<=W-ori.w;x++){
                    int my=0;for(auto[cx,cy]:ori.cells)my=max(my,hmap[x+cx]-cy);
                    int top=0;for(auto[cx,cy]:ori.cells)top=max(top,my+cy+1);
                    if(top>maxH)continue;
                    bool ok=true;for(auto[cx,cy]:ori.cells){int py=my+cy;if(py<0||py>=maxH||grid[x+cx][py]){ok=false;break;}}
                    if(!ok)continue;
                    int sc=top*10000+x;if(sc<bs){bs=sc;bx=x;by=my;bo=oi;}
                }
            }
            if(bx<0){fail=true;break;}
            auto&ori=allOris[pi][bo];
            for(auto[cx,cy]:ori.cells){grid[bx+cx][by+cy]=true;hmap[bx+cx]=max(hmap[bx+cx],by+cy+1);curMax=max(curMax,by+cy+1);}
            pl[pi]={bx,by,ori.r,ori.f};
        }
        if(fail)continue;
        long long area=(long long)W*curMax;
        if(area<bestArea){bestArea=area;bestH=curMax;bestW=W;bestPl=pl;}
    }
    if(bestArea>=4e18){int cx=0;bestH=0;for(int i=0;i<n;i++){auto&o=allOris[i][0];bestPl[i]={cx,0,o.r,o.f};cx+=o.w;bestH=max(bestH,o.h);}bestW=cx;}
    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++)cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
